ValidationRule.errorConditionFormula:
AND(
  /* Fire only on existing records */
  NOT(ISNEW()),

  /* Scope to General Task record type only */
  RecordType.DeveloperName = "General",

  /* Fire only when Description (Area__c) changes */
  ISCHANGED(Area__c),

  /* Fire only before completion */
  NOT(
    OR(
      ISPICKVAL(Status, "Completed"),
      ISPICKVAL(PRIORVALUE(Status), "Completed")
    )
  ),

  /* Block unauthorized users */
  NOT(
    OR(
      /* Allow: Task Initiator */
      $User.Id = Initiated_by__c,

      /* Allow: Task Initiator who is also the Assignee */
      AND(
        $User.Id = OwnerId,
        OwnerId = Initiated_by__c
      ),

      /* Allow: Corporate Business Admin (Read Only profile) */
      $Profile.Name = "Read Only",

      /* Allow: Corporate Salesforce Team */
      $Profile.Name = "Corporate salesforce team",

      /* Allow: System Administrator */
      $Profile.Name = "System Administrator"
    )
  )
)
